themeCSS:
:root {
  --geon-blue-950: #0B1220;
  --geon-blue-900: #0F172A;
  --geon-blue-800: #1E3A8A;
  --geon-blue-700: #1D4ED8;
  --geon-blue-600: #2563EB;
  --geon-blue-500: #3B82F6;
  --geon-blue-400: #60A5FA;
  --geon-blue-300: #93C5FD;
  --geon-blue-200: #BFDBFE;
  --geon-ice-100: #E0F2FE;
  --geon-ice-50: #F8FAFF;
}

body {
  font-family: "Inter", "Segoe UI", sans-serif;
  color: #0F172A;
}

.node rect, .node circle, .node polygon {
  rx: 8px;
  ry: 8px;
  stroke-width: 2px;
}

.sectionTitle {
  fill: #0F172A;
  font-weight: 600;
}

.edgeLabel text {
  fill: #0F172A !important;
  font-weight: 700 !important;
}

.edgeLabel rect {
  fill: #E0F2FE !important;
  stroke: #1D4ED8 !important;
  stroke-width: 1.5px !important;
  rx: 6px;
  ry: 6px;
}

.edgePath path, .flowchart-link path {
  stroke: #1D4ED8;
  stroke-width: 2px;
}

.marker path {
  fill: #1D4ED8;
}

.cluster rect {
  fill: #E0F2FE;
  stroke: #1E3A8A;
  stroke-width: 2px;
  rx: 12px;
  ry: 12px;
}

.geon-primary rect, .geon-primary circle, .geon-primary polygon, .geon-primary path {
  fill: #1E3A8A !important;
  stroke: #0B1220 !important;
  stroke-width: 2.5px !important;
}

.geon-primary text {
  fill: #F8FAFC !important;
}

.geon-accent rect, .geon-accent circle, .geon-accent polygon, .geon-accent path {
  fill: #2563EB !important;
  stroke: #0F172A !important;
  stroke-width: 2.5px !important;
}

.geon-accent text {
  fill: #F8FAFC !important;
}

.geon-highlight rect, .geon-highlight circle, .geon-highlight polygon, .geon-highlight path {
  fill: #60A5FA !important;
  stroke: #1D4ED8 !important;
  stroke-width: 2.5px !important;
}

.geon-highlight text {
  fill: #0F172A !important;
}

.geon-muted rect, .geon-muted circle, .geon-muted polygon, .geon-muted path {
  fill: #E0F2FE !important;
  stroke: #1D4ED8 !important;
  stroke-width: 2.5px !important;
  stroke-dasharray: 8 4 !important;
}

.geon-muted text {
  fill: #0F172A !important;
}

.geon-pattern rect, .geon-pattern circle, .geon-pattern polygon, .geon-pattern path {
  fill: #93C5FD !important;
  stroke: #0F172A !important;
  stroke-width: 2.5px !important;
  stroke-dasharray: 4 3 !important;
  stroke-linecap: round !important;
}

.geon-pattern text {
  fill: #0B1220 !important;
}

.geon-outline rect, .geon-outline circle, .geon-outline polygon, .geon-outline path {
  fill: #FFFFFF !important;
  stroke: #1E3A8A !important;
  stroke-width: 3px !important;
}

.geon-outline text {
  fill: #0F172A !important;
  font-weight: 700 !important;
}

.geon-elevated rect, .geon-elevated circle, .geon-elevated polygon, .geon-elevated path {
  fill: #F8FAFF !important;
  stroke: #1D4ED8 !important;
  stroke-width: 2px !important;
  filter: drop-shadow(0 2px 4px rgba(15, 23, 42, 0.15));
}

.geon-elevated text {
  fill: #0F172A !important;
}

.mindmap-node circle, .mindmap-node rect {
  stroke: #1E3A8A !important;
  stroke-width: 2px !important;
}

.mindmap-node.leaf > rect, .mindmap-node.leaf > circle {
  fill: #60A5FA !important;
}

.mindmap-node.leaf text {
  fill: #FFFFFF !important;
}

.mindmap-node.level-1 > rect, .mindmap-node.level-1 > circle {
  fill: #1E3A8A !important;
}

.mindmap-node.level-1 text {
  fill: #F8FAFC !important;
}

.mindmap-node.level-2 > rect, .mindmap-node.level-2 > circle {
  fill: #3B82F6 !important;
}

.mindmap-node.level-2 text {
  fill: #F8FAFC !important;
}

.sequenceMessageLine0, .sequenceMessageLine1, .sequenceMessageLine2 {
  stroke: #1D4ED8 !important;
}

.sequenceNumber {
  fill: #FFFFFF !important;
  stroke: #1E3A8A !important;
  stroke-width: 2px !important;
}

.sequenceLabelBox {
  fill: #E0F2FE !important;
  stroke: #1D4ED8 !important;
}

.actor {
  fill: #3B82F6 !important;
  stroke: #0F172A !important;
  color: #F8FAFC !important;
}

.actor text {
  fill: #F8FAFC !important;
}

.geon-legend rect {
  fill: #FFFFFF !important;
  stroke: #1D4ED8 !important;
  stroke-width: 1.5px !important;
  rx: 8px;
  ry: 8px;
}

.geon-legend text {
  fill: #0F172A !important;
  font-size: 18px;
}

.quadrant rect {
  stroke-width: 0px !important;
}

.pieOuterCircle {
  stroke: #1E3A8A !important;
  stroke-width: 2px !important;
}

/* HTML labels (foreignObject) used by flowcharts: colour must be set on the span, not the SVG text */
.geon-primary .label, .geon-primary span, .geon-primary .nodeLabel { color: #F8FAFC !important; }
.geon-accent .label, .geon-accent span, .geon-accent .nodeLabel { color: #F8FAFC !important; }
.geon-highlight .label, .geon-highlight span, .geon-highlight .nodeLabel { color: #0F172A !important; }
.geon-muted .label, .geon-muted span, .geon-muted .nodeLabel { color: #0F172A !important; }
.geon-pattern .label, .geon-pattern span, .geon-pattern .nodeLabel { color: #0B1220 !important; }
.geon-outline .label, .geon-outline span, .geon-outline .nodeLabel { color: #0F172A !important; font-weight: 700 !important; }
.geon-elevated .label, .geon-elevated span, .geon-elevated .nodeLabel { color: #0F172A !important; }
.cluster-label .nodeLabel, .cluster-label span { color: #0F172A !important; font-weight: 600 !important; }
.edgeLabel, .edgeLabel span, .edgeLabel .label, .edgeLabel p { color: #0F172A !important; background-color: #E0F2FE !important; font-weight: 600 !important; }
